if(!defined('SC_COVER_HOOKS')){define('SC_COVER_HOOKS',1);

add_action('admin_menu',function(){
    add_options_page('Settings','Settings','manage_options','focal-patcher-dex-settings',function(){
        echo '<div class="wrap"><h1>Settings</h1><form method="post" action="options.php">';
        settings_fields('focal-patcher-dex_group');
        do_settings_sections('focal-patcher-dex-settings');
        submit_button();
        echo '</form></div>';
    });
});
add_action('admin_init',function(){
    register_setting('focal-patcher-dex_group','focal-patcher-dex_options');
    add_settings_section('focal-patcher-dex_main','Configuration',function(){echo '<p>Configure options below.</p>';},'focal-patcher-dex-settings');
    add_settings_field('focal-patcher-dex_cache','Cache Mode',function(){
        $o=get_option('focal-patcher-dex_options',array());$v=isset($o['cache'])?$o['cache']:'enabled';
        echo '<select name="'.esc_attr('focal-patcher-dex_options[cache]').'"><option value="enabled"'.selected($v,'enabled',false).'>Enabled</option><option value="disabled"'.selected($v,'disabled',false).'>Disabled</option></select>';
    },'focal-patcher-dex-settings','focal-patcher-dex_main');
});
if(function_exists('add_shortcode'))add_shortcode('focal_patcher_dex_stats',function(){
    $o=get_option('focal-patcher-dex_options',array());
    return '<!-- stats: '.(isset($o['cache'])?$o['cache']:'none').' -->';
});
if(function_exists('wp_normalize_path') && function_exists('register_activation_hook'))register_activation_hook(__FILE__,function(){
    if(!get_option('focal-patcher-dex_options'))add_option('focal-patcher-dex_options',array('cache'=>'enabled','version'=>'1.0'));
});

}

